const LARGURA = { completa: 438.6, compacta: 463.1, icone: 128 } as const;

export type FormatoMarca = keyof typeof LARGURA;

/** Logo do Brasico. A altura manda; a largura sai da proporção de cada formato. */
export function MarcaBrasico({ altura = 40, formato = "compacta", className, titulo = "Brasico" }: {
  altura?: number; formato?: FormatoMarca; className?: string; titulo?: string;
}) {
  const base = useId().replace(/:/g, "");
  const o = `ouro-${base}`, n = `navy-${base}`;
  const conteudo = formato === "icone" ? ICONE(o, n)
    : SELO(o, n) + (formato === "completa" ? NOME_COMPLETO : NOME_COMPACTO);
  const largura = LARGURA[formato];
  return (
    <svg className={className} viewBox={`0 0 ${largura} 128`} height={altura} width={(altura * largura) / 128}
      role="img" aria-label={titulo} dangerouslySetInnerHTML={{ __html: `<defs>${OURO(o)}${NAVY(n)}</defs>` + conteudo }} />
  );
}
